BEGIN
 IF CURRENT_USER<>'cinatoken_gateway_migrator' OR SESSION_USER<>CURRENT_USER
  OR current_setting('session_replication_role')<>'origin'
  OR current_setting('cinatoken.complete_text_auth_routing_recovery_coinstall_v400_activation',true) IS DISTINCT FROM 'reviewed-v1'
  OR (SELECT count(*) FROM cinatoken_gateway.schema_migrations)<>73
  OR (SELECT md5(string_agg(version,E'\n' ORDER BY version COLLATE "C")) FROM cinatoken_gateway.schema_migrations) IS DISTINCT FROM 'ca1ea96a1b4bcd0675642f30dcf48042'
 THEN RAISE EXCEPTION 'v400 preflight activation or PG73 differs' USING ERRCODE='P0001'; END IF;
 IF EXISTS(SELECT 1 FROM pg_db_role_setting s LEFT JOIN pg_roles r ON r.oid=s.setrole
  WHERE r.rolname LIKE 'cinatoken_%' OR (s.setrole=0 AND s.setdatabase IN(0,(SELECT oid FROM pg_database WHERE datname=current_database()))))
  OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname LIKE 'cinatoken_%' AND r.rolname<>'cinatoken_gateway_migrator'
    AND has_parameter_privilege(r.oid,'session_replication_role','SET'))
 THEN RAISE EXCEPTION 'v400 preflight role settings or replication parameter authority differs' USING ERRCODE='P0001'; END IF;
 IF EXISTS(SELECT 1 FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname LIKE 'cinatoken_%' OR c.relowner=(SELECT oid FROM pg_roles WHERE rolname='cinatoken_gateway_migrator'))
 THEN RAISE EXCEPTION 'v400 preflight relation policy inventory differs' USING ERRCODE='P0001'; END IF;
 SELECT jsonb_build_object(
 'functions',COALESCE((SELECT jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'kind',p.prokind,'returns_set',p.proretset,'parallel',p.proparallel,'strict',p.proisstrict,'leakproof',p.proleakproof,
  'security_definer',p.prosecdef,'volatility',p.provolatile,'return_type',p.prorettype::regtype::text,
  'arguments',pg_get_function_arguments(p.oid),'result_definition',pg_get_function_result(p.oid),
  'config',to_jsonb(p.proconfig),'body_md5',md5(replace(p.prosrc,E'\r\n',E'\n')),
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
   'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
   ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",a.privilege_type COLLATE "C")
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a)) ORDER BY p.oid::regprocedure::text COLLATE "C")
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname LIKE 'cinatoken_%' OR p.proowner=(SELECT oid FROM pg_roles WHERE rolname='cinatoken_gateway_migrator')),'[]'::jsonb),
 'relations',COALESCE((SELECT jsonb_agg(jsonb_build_object(
  'name',c.oid::regclass::text,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
   'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
   ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",a.privilege_type COLLATE "C")
   FROM aclexplode(COALESCE(c.relacl,acldefault((CASE WHEN c.relkind='S' THEN 's' ELSE 'r' END)::"char",c.relowner))) a),
  'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
   'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),
   'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,
   'acl',COALESCE((SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
    'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable)
    ORDER BY (CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END) COLLATE "C",x.privilege_type COLLATE "C") FROM aclexplode(a.attacl) x),'[]'::jsonb)) ORDER BY a.attnum)
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'::jsonb),
  'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',x.conname,'type',x.contype,'deferrable',x.condeferrable,
   'initially_deferred',x.condeferred,'validated',x.convalidated,'definition',pg_get_constraintdef(x.oid)) ORDER BY x.conname COLLATE "C")
   FROM pg_constraint x WHERE x.conrelid=c.oid),'[]'::jsonb),
  'rules',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',x.rulename,'enabled',x.ev_enabled,'definition',pg_get_ruledef(x.oid)) ORDER BY x.rulename COLLATE "C")
   FROM pg_rewrite x WHERE x.ev_class=c.oid),'[]'::jsonb)) ORDER BY c.oid::regclass::text COLLATE "C")
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname LIKE 'cinatoken_%' OR c.relowner=(SELECT oid FROM pg_roles WHERE rolname='cinatoken_gateway_migrator')) AND c.relkind IN('r','p','v','m','f','S')),'[]'::jsonb),
 'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,
  'function',t.tgfoid::regprocedure::text,'enabled',t.tgenabled,'type',t.tgtype,'qual',t.tgqual::text,'columns',t.tgattr::text,
  'arguments',encode(t.tgargs,'hex'),'argument_count',t.tgnargs,'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred,
  'old_table',t.tgoldtable,'new_table',t.tgnewtable,'constraint',t.tgconstraint<>0,'constraint_table',CASE WHEN t.tgconstrrelid=0 THEN NULL ELSE t.tgconstrrelid::regclass::text END,
  'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgrelid::regclass::text COLLATE "C",t.tgname COLLATE "C")
  FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname LIKE 'cinatoken_%' AND NOT t.tgisinternal),'[]'::jsonb),
 'schemas',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
   'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
   ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",a.privilege_type COLLATE "C")
   FROM aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) a)) ORDER BY n.nspname COLLATE "C") FROM pg_namespace n WHERE n.nspname LIKE 'cinatoken_%'),'[]'::jsonb),
 'principals',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'login',r.rolcanlogin,'inherit',r.rolinherit,
  'super',r.rolsuper,'create_role',r.rolcreaterole,'create_database',r.rolcreatedb,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls,
  'connection_limit',r.rolconnlimit,'config',to_jsonb(r.rolconfig),
  'database_create',has_database_privilege(r.oid,current_database(),'CREATE'),'public_create',has_schema_privilege(r.oid,'public','CREATE'),
  'memberships',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),
   'grantor',pg_get_userbyid(m.grantor),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option)
   ORDER BY pg_get_userbyid(m.roleid) COLLATE "C",pg_get_userbyid(m.member) COLLATE "C") FROM pg_auth_members m WHERE m.roleid=r.oid OR m.member=r.oid),'[]'::jsonb))
  ORDER BY r.rolname COLLATE "C") FROM pg_roles r WHERE r.rolname LIKE 'cinatoken_%'),'[]'::jsonb),
 'defaults',COALESCE((SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace=0 THEN NULL ELSE n.nspname END,
  'type',d.defaclobjtype,'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
   'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
   ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",a.privilege_type COLLATE "C") FROM aclexplode(d.defaclacl) a))
  ORDER BY pg_get_userbyid(d.defaclrole) COLLATE "C",COALESCE(n.nspname,'') COLLATE "C",d.defaclobjtype)
  FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclrole=(SELECT oid FROM pg_roles WHERE rolname='cinatoken_gateway_migrator')),'[]'::jsonb)
) INTO actual;
 FOR category IN SELECT jsonb_object_keys(expected) LOOP
  IF actual->category IS DISTINCT FROM expected->category THEN
   SELECT item INTO difference FROM (SELECT value item FROM jsonb_array_elements(actual->category) EXCEPT SELECT value FROM jsonb_array_elements(expected->category)) d LIMIT 1;
   RAISE EXCEPTION 'v400 preflight catalog differs: %',category USING ERRCODE='P0001',DETAIL=left(coalesce(difference::text,'missing expected object'),8000);
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN('cinatoken_gateway_complete_text_routing_projector','cinatoken_gateway_complete_text_sticky_router') AND
  (has_database_privilege(r.oid,current_database(),'CREATE') OR EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND has_schema_privilege(r.oid,n.oid,'CREATE'))))
 OR EXISTS(SELECT 1 FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE r.rolname IN('cinatoken_gateway_complete_text_routing_projector','cinatoken_gateway_complete_text_sticky_router') AND n.nspname NOT IN('pg_catalog','information_schema') AND
   CASE WHEN c.relkind IN('r','p','v','m','f') THEN has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') OR has_any_column_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE')
    WHEN c.relkind='S' THEN has_sequence_privilege(r.oid,c.oid,'SELECT,USAGE,UPDATE') ELSE false END)
 OR EXISTS(SELECT 1 FROM pg_roles r CROSS JOIN pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE r.rolname IN('cinatoken_gateway_complete_text_routing_projector','cinatoken_gateway_complete_text_sticky_router') AND n.nspname NOT IN('pg_catalog','information_schema')
   AND has_function_privilege(r.oid,p.oid,'EXECUTE') AND NOT(false))
 THEN RAISE EXCEPTION 'v400 preflight new LOGIN authority differs' USING ERRCODE='P0001'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r CROSS JOIN pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE r.rolname LIKE 'cinatoken_%' AND r.rolname<>'cinatoken_gateway_migrator' AND n.nspname NOT LIKE 'cinatoken_%'
   AND n.nspname NOT IN('pg_catalog','information_schema') AND has_function_privilege(r.oid,p.oid,'EXECUTE'))
 OR EXISTS(SELECT 1 FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE r.rolname LIKE 'cinatoken_%' AND r.rolname<>'cinatoken_gateway_migrator' AND n.nspname NOT LIKE 'cinatoken_%'
   AND n.nspname NOT IN('pg_catalog','information_schema') AND CASE WHEN c.relkind IN('r','p','v','m','f')
    THEN has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') OR has_any_column_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE')
    WHEN c.relkind='S' THEN has_sequence_privilege(r.oid,c.oid,'SELECT,USAGE,UPDATE') ELSE false END)
 THEN RAISE EXCEPTION 'v400 preflight outside-schema authority differs' USING ERRCODE='P0001'; END IF;
END;
$preflight$;
-- BEGIN narrow v362 inherited grant typed-row declaration repair
CREATE OR REPLACE FUNCTION cinatoken_gateway.grant_complete_flat_text_attempt_v362(
  p_attempt_nonce uuid,p_claim jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path TO pg_catalog, pg_temp
SET lock_timeout TO '2s'
SET statement_timeout TO '15s' AS $grant$
DECLARE required_key text; key_count integer; v_request_id text; v_quote_id uuid;
DECLARE claim_sha text; prior record; q record; admission record; cap record;
DECLARE key_row record; user_row record; workspace_row record;
DECLARE manifest record; chosen record; ordinary cinatoken_gateway.user_budget_reservations%ROWTYPE; held record;
DECLARE intent record; source_row record; window_row record;
DECLARE server_now timestamptz; send_expires timestamptz;
DECLARE recovery_expires timestamptz; expected_start timestamptz;
DECLARE expected_end timestamptz; active_micros bigint; expected_count integer;
DECLARE manifest_count integer; active_count integer; candidate_count integer;
DECLARE max_ceiling bigint; guardrail_count integer:=0; supplied_key integer:=0;
DECLARE supplied_workspace integer:=0; supplied_configured integer:=0;
DECLARE seen_assignments text[]:=ARRAY[]::text[];
DECLARE grant_uuid uuid; v_attempt_number integer;
BEGIN
  IF SESSION_USER<>'cinatoken_gateway_complete_text_attempt_granter'
    OR pg_catalog.current_setting('transaction_isolation')<>'read committed'
    OR p_attempt_nonce IS NULL
    OR pg_catalog.jsonb_typeof(p_claim) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'invalid complete text attempt grant call'
    USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_grant_call_v362'; END IF;
  SELECT pg_catalog.count(*)::integer INTO key_count
    FROM pg_catalog.jsonb_object_keys(p_claim);
  IF key_count<>18 THEN RAISE EXCEPTION 'invalid complete text attempt claim shape'
    USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_claim_v362'; END IF;
  FOREACH required_key IN ARRAY ARRAY['requestId','quoteId','finalBodySha256',
    'candidateIndex','modelId','routeTargetId','providerId','endpointId',
    'credentialClass','credentialId','providerCiphertextSha256',
    'preparedRouteSourceSha256','method','upstreamUrlSha256',
    'outboundBodySha256','outboundBodyCanonicalSha256','outboundBodyBytes',
    'credentialFingerprintSha256'] LOOP
    IF NOT p_claim ? required_key OR p_claim->required_key='null'::jsonb
    THEN RAISE EXCEPTION 'missing complete text attempt claim field'
      USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_claim_v362'; END IF;
  END LOOP;
  IF pg_catalog.jsonb_typeof(p_claim->'requestId')<>'string'
    OR pg_catalog.length(p_claim->>'requestId') NOT BETWEEN 1 AND 128
    OR pg_catalog.jsonb_typeof(p_claim->'quoteId')<>'string'
    OR (p_claim->>'quoteId') !~
      '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    OR pg_catalog.jsonb_typeof(p_claim->'candidateIndex')<>'number'
    OR (p_claim->>'candidateIndex') !~ '^[0-7]$'
    OR pg_catalog.jsonb_typeof(p_claim->'outboundBodyBytes')<>'number'
    OR (p_claim->>'outboundBodyBytes') !~ '^[0-9]{1,7}$'
    OR (p_claim->>'outboundBodyBytes')::integer NOT BETWEEN 2 AND 2097152
    OR p_claim->>'credentialClass' IS DISTINCT FROM 'platform'
    OR p_claim->>'method' IS DISTINCT FROM 'POST'
  THEN RAISE EXCEPTION 'invalid complete text attempt claim value'
    USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_claim_v362'; END IF;
  FOREACH required_key IN ARRAY ARRAY['finalBodySha256',
    'providerCiphertextSha256','preparedRouteSourceSha256',
    'upstreamUrlSha256','outboundBodySha256','outboundBodyCanonicalSha256',
    'credentialFingerprintSha256'] LOOP
    IF pg_catalog.jsonb_typeof(p_claim->required_key)<>'string'
      OR (p_claim->>required_key) !~ '^[0-9a-f]{64}$'
    THEN RAISE EXCEPTION 'invalid complete text attempt claim digest'
      USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_claim_v362'; END IF;
  END LOOP;
  FOREACH required_key IN ARRAY ARRAY['modelId','routeTargetId',
    'providerId','endpointId','credentialId'] LOOP
    IF pg_catalog.jsonb_typeof(p_claim->required_key)<>'string'
      OR pg_catalog.length(p_claim->>required_key) NOT BETWEEN 1 AND 512
    THEN RAISE EXCEPTION 'invalid complete text attempt claim identity'
      USING ERRCODE='23514',CONSTRAINT='complete_text_attempt_claim_v362'; END IF;
  END LOOP;
  v_request_id:=p_claim->>'requestId';
  v_quote_id:=(p_claim->>'quoteId')::uuid;
  claim_sha:=pg_catalog.encode(pg_catalog.sha256(
    pg_catalog.convert_to(p_claim::text,'UTF8')),'hex');

  -- v361 and v351 use this key. Unknown ACK replay cannot obtain another
  -- fresh grant, even through a separate direct LOGIN connection.
  PERFORM pg_catalog.pg_advisory_xact_lock(348,pg_catalog.hashtext(v_request_id));
  SELECT * INTO q FROM cinatoken_gateway.complete_text_quotes_v360
    WHERE request_id=v_request_id AND quote_id=v_quote_id FOR SHARE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','missing_quote'); END IF;
  SELECT * INTO prior FROM cinatoken_gateway.complete_text_attempt_grants_v362
    WHERE request_id=v_request_id AND attempt_nonce=p_attempt_nonce FOR SHARE;
  IF FOUND THEN
    IF prior.quote_id IS DISTINCT FROM v_quote_id
      OR prior.claim_sha256 IS DISTINCT FROM claim_sha
    THEN RETURN pg_catalog.jsonb_build_object('status','nonce_conflict'); END IF;
    RETURN pg_catalog.jsonb_build_object('status','already_recorded_unknown',
      'grantId',prior.grant_id,'attemptNumber',prior.attempt_number);
  END IF;
  IF EXISTS (SELECT 1 FROM cinatoken_gateway.complete_text_attempt_grants_v362
      WHERE request_id=v_request_id)
  THEN RETURN pg_catalog.jsonb_build_object('status','pending_unknown'); END IF;
  SELECT * INTO admission FROM cinatoken_gateway.complete_text_admissions_v361
    WHERE request_id=v_request_id AND quote_id=v_quote_id FOR SHARE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','admission_required'); END IF;
  SELECT * INTO cap FROM cinatoken_gateway.authenticated_request_capabilities_v356
    WHERE request_id=v_request_id FOR SHARE;
  SELECT * INTO key_row FROM cinatoken_gateway.api_keys
    WHERE id=q.api_key_id FOR SHARE;
  SELECT * INTO user_row FROM cinatoken_gateway.users
    WHERE id=q.user_id FOR UPDATE;
  SELECT * INTO workspace_row FROM cinatoken_gateway.workspaces
    WHERE id=q.workspace_id FOR SHARE;
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR admission.expires_at<=server_now
    OR admission.final_body_sha256 IS DISTINCT FROM q.final_body_sha256
    OR admission.reserved_micros IS DISTINCT FROM q.three_attempt_ceiling_micros
    OR admission.ordinary_status NOT IN ('reserved','unlimited')
    OR cap.request_id IS NULL OR cap.state<>'claimed'
    OR cap.invalidated_at IS NOT NULL
    OR cap.body_sha256 IS DISTINCT FROM q.original_body_sha256
    OR cap.api_key_id IS DISTINCT FROM q.api_key_id
    OR cap.user_id IS DISTINCT FROM q.user_id
    OR cap.workspace_id IS DISTINCT FROM q.workspace_id
    OR cap.budget_epoch IS DISTINCT FROM q.budget_epoch
    OR cap.key_limit_epoch IS DISTINCT FROM q.key_limit_epoch
    OR key_row.id IS NULL OR key_row.status IS DISTINCT FROM 'active'
    OR key_row.key_hash IS DISTINCT FROM cap.key_hash
    OR key_row.key IS DISTINCT FROM 'hashref:'||cap.key_hash
    OR key_row.user_id IS DISTINCT FROM q.user_id
    OR key_row.workspace_id IS DISTINCT FROM q.workspace_id
    OR key_row.limit_epoch IS DISTINCT FROM q.key_limit_epoch
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
    OR user_row.id IS NULL OR user_row.status IS DISTINCT FROM 'active'
    OR user_row.budget_epoch IS DISTINCT FROM q.budget_epoch
    OR user_row.charged_cost_factors IS NOT NULL
    OR workspace_row.id IS NULL OR workspace_row.status IS DISTINCT FROM 'active'
    OR workspace_row.scope_type IS DISTINCT FROM 'personal'
    OR workspace_row.personal_owner_user_id IS DISTINCT FROM q.user_id
    OR q.credential_class IS DISTINCT FROM 'platform'
    OR p_claim->>'finalBodySha256' IS DISTINCT FROM q.final_body_sha256
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;

  -- Conservative predicate locks prevent a new route, BYOK source, surface,
  -- Guardrail config or extra reservation from appearing between validation
  -- and COMMIT. This serializes unrelated budget writes in the review proof.
  LOCK TABLE cinatoken_gateway.models,cinatoken_gateway.model_surfaces,
    cinatoken_gateway.model_routes,cinatoken_gateway.route_pools,
    cinatoken_gateway.providers,cinatoken_gateway.model_endpoints,
    cinatoken_gateway.model_endpoint_routes,
    cinatoken_gateway.route_source_generations_v359,
    cinatoken_gateway.byok_keys,cinatoken_gateway.guardrails,
    cinatoken_gateway.guardrail_versions,
    cinatoken_gateway.guardrail_assignments,
    cinatoken_gateway.workspace_budgets IN SHARE MODE;
  LOCK TABLE cinatoken_gateway.user_budget_reservations,
    cinatoken_gateway.guardrail_budget_reservations,
    cinatoken_gateway.guardrail_budget_windows IN SHARE ROW EXCLUSIVE MODE;
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR admission.expires_at<=server_now
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.byok_keys b
      WHERE b.workspace_id=q.workspace_id AND b.deleted_at IS NULL
        AND NOT b.disabled)
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;

  candidate_count:=pg_catalog.jsonb_array_length(q.ordered_model_ids);
  SELECT pg_catalog.count(*)::integer,
    pg_catalog.max(per_attempt_ceiling_micros)
    INTO manifest_count,max_ceiling
    FROM cinatoken_gateway.complete_text_quote_routes_v360
    WHERE quote_id=q.quote_id;
  IF candidate_count NOT BETWEEN 1 AND 8 OR manifest_count<>q.route_count
    OR manifest_count<1 OR max_ceiling IS NULL OR max_ceiling<=0
    OR max_ceiling<>q.max_per_attempt_ceiling_micros
    OR q.three_attempt_ceiling_micros<>max_ceiling*3
  THEN RETURN pg_catalog.jsonb_build_object('status','invalid_manifest'); END IF;
  FOR manifest IN SELECT * FROM cinatoken_gateway.complete_text_quote_routes_v360
    WHERE quote_id=q.quote_id ORDER BY candidate_index,route_target_id
  LOOP
    IF manifest.candidate_index>=candidate_count
      OR manifest.model_id IS DISTINCT FROM
        q.ordered_model_ids->>manifest.candidate_index
      OR manifest.credential_class IS DISTINCT FROM 'platform'
      OR manifest.credential_id IS DISTINCT FROM manifest.provider_id
      OR manifest.source_sha256 IS DISTINCT FROM pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(
          manifest.source_snapshot::text,'UTF8')),'hex')
      OR manifest.source_snapshot->>'modelId' IS DISTINCT FROM manifest.model_id
      OR manifest.source_snapshot->>'routeTargetId' IS DISTINCT FROM manifest.route_target_id
      OR manifest.source_snapshot->>'providerId' IS DISTINCT FROM manifest.provider_id
      OR manifest.source_snapshot->>'endpointId' IS DISTINCT FROM manifest.endpoint_id
      OR manifest.source_snapshot->>'providerCiphertextSha256'
        IS DISTINCT FROM manifest.provider_ciphertext_sha256
      OR manifest.source_snapshot->>'attestedSourceSha256'
        IS DISTINCT FROM manifest.attested_source_sha256
      OR manifest.source_snapshot->>'sourceGeneration'
        IS DISTINCT FROM manifest.source_generation::text
      OR NOT EXISTS (SELECT 1 FROM cinatoken_gateway.model_routes r
        JOIN cinatoken_gateway.route_pools rp
          ON rp.id=r.route_pool_id AND rp.model_id=r.model_id
            AND rp.route_group=r.route_group
        JOIN cinatoken_gateway.providers po ON po.id=r.provider_id
        JOIN cinatoken_gateway.model_endpoint_routes er
          ON er.route_target_id=r.id
        JOIN cinatoken_gateway.model_endpoints e
          ON e.id=er.endpoint_id AND e.model_id=r.model_id
            AND e.provider_id=r.provider_id
        JOIN cinatoken_gateway.route_source_generations_v359 f
          ON f.route_target_id=r.id
        WHERE r.id=manifest.route_target_id AND r.model_id=manifest.model_id
          AND r.provider_id=manifest.provider_id
          AND r.status='active' AND r.route_group='default'
          AND r.upstream_protocol='openai' AND r.upstream_operation='chat'
          AND r.adapter='passthrough' AND r.price_override IS NULL
          AND r.custom_params IS NULL AND r.routing_metadata IS NULL
          AND rp.status='active' AND po.status='active'
          AND po.shared_channel_type IS NULL AND po.api_key LIKE 'enc:v2:%'
          AND pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(po.api_key,'UTF8')),'hex')
              =manifest.provider_ciphertext_sha256
          AND e.id=manifest.endpoint_id AND e.status='verified'
          AND e.expires_at>server_now
          AND f.generation=manifest.source_generation
          AND f.verified_generation=f.generation
          AND f.attested_source_sha256=manifest.attested_source_sha256
          AND f.verified_subject_fingerprint=er.subject_fingerprint)
    THEN RETURN pg_catalog.jsonb_build_object('status','stale_manifest'); END IF;
  END LOOP;
  SELECT pg_catalog.count(*)::integer INTO active_count
    FROM pg_catalog.jsonb_array_elements_text(q.ordered_model_ids)
      WITH ORDINALITY AS candidates(model_id,ordinal)
    JOIN cinatoken_gateway.model_routes r
      ON r.model_id=candidates.model_id AND r.status='active';
  IF active_count<>manifest_count OR EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_array_elements_text(q.ordered_model_ids)
      WITH ORDINALITY AS candidates(model_id,ordinal)
    JOIN cinatoken_gateway.model_routes r
      ON r.model_id=candidates.model_id AND r.status='active'
    WHERE NOT EXISTS (SELECT 1
      FROM cinatoken_gateway.complete_text_quote_routes_v360 m
      WHERE m.quote_id=q.quote_id AND m.candidate_index=candidates.ordinal-1
        AND m.route_target_id=r.id))
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.model_surfaces s
      JOIN cinatoken_gateway.route_pools rp ON rp.id=s.route_pool_id
      WHERE s.model_id IN (SELECT value FROM pg_catalog.jsonb_array_elements_text(
          q.ordered_model_ids)) AND lower(s.route_group)='default'
        AND lower(s.request_protocol)='openai'
        AND s.request_operation IN ('chat','*') AND s.status='active'
        AND rp.status='active' AND (rp.model_id<>s.model_id OR EXISTS (
          SELECT 1 FROM cinatoken_gateway.model_routes sr
          WHERE sr.route_pool_id=s.route_pool_id AND sr.status='active'
            AND sr.model_id<>s.model_id)))
  THEN RETURN pg_catalog.jsonb_build_object('status','stale_manifest'); END IF;
  SELECT * INTO chosen FROM cinatoken_gateway.complete_text_quote_routes_v360
    WHERE quote_id=q.quote_id
      AND candidate_index=(p_claim->>'candidateIndex')::integer
      AND route_target_id=p_claim->>'routeTargetId';
  IF NOT FOUND OR chosen.model_id IS DISTINCT FROM p_claim->>'modelId'
    OR chosen.provider_id IS DISTINCT FROM p_claim->>'providerId'
    OR chosen.endpoint_id IS DISTINCT FROM p_claim->>'endpointId'
    OR chosen.credential_class IS DISTINCT FROM p_claim->>'credentialClass'
    OR chosen.credential_id IS DISTINCT FROM p_claim->>'credentialId'
    OR chosen.provider_ciphertext_sha256 IS DISTINCT FROM
      p_claim->>'providerCiphertextSha256'
  THEN RETURN pg_catalog.jsonb_build_object('status','target_not_in_manifest'); END IF;

  -- v361's recorded source intents are rechecked against current sources.
  -- The empty-intent case must prove there is still no applicable source.
  IF admission.guardrail_count=0 AND (key_row.limit_micros IS NOT NULL
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.workspace_budgets wb
      WHERE wb.workspace_id=q.workspace_id)
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.guardrails g
      JOIN cinatoken_gateway.guardrail_versions v
        ON v.guardrail_id=g.id AND v.version=g.designated_version
      LEFT JOIN cinatoken_gateway.guardrail_assignments ga
        ON NOT g.is_workspace_default AND ga.guardrail_id=g.id
          AND ga.workspace_id=q.workspace_id
          AND ((ga.scope_type='user' AND ga.scope_id=q.user_id)
            OR (ga.scope_type='api_key' AND ga.scope_id=q.api_key_id))
      WHERE g.workspace_id=q.workspace_id AND g.status='active'
        AND NOT g.is_account_default
        AND (g.is_workspace_default OR ga.id IS NOT NULL)
        AND v.config_json::jsonb->'budget' IS NOT NULL
        AND v.config_json::jsonb->'budget'<>'null'::jsonb))
  THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
  IF admission.guardrail_count<>pg_catalog.jsonb_array_length(
      admission.guardrail_intents)
  THEN RETURN pg_catalog.jsonb_build_object('status','invalid_admission'); END IF;
  FOR intent IN SELECT * FROM pg_catalog.jsonb_to_recordset(
      admission.guardrail_intents) AS x(
      "workspaceId" text,"assignmentId" text,"guardrailId" text,
      "guardrailVersion" integer,"scopeType" text,"scopeId" text,
      period text,"periodStart" timestamptz,"periodEnd" timestamptz,
      "limitMicros" bigint)
    ORDER BY "workspaceId","scopeType","scopeId",period,"periodStart",
      "assignmentId"
  LOOP
    guardrail_count:=guardrail_count+1;
    IF intent."workspaceId" IS DISTINCT FROM q.workspace_id
      OR intent."assignmentId" IS NULL
      OR intent."assignmentId"=ANY(seen_assignments)
      OR intent."periodStart" IS NULL OR intent."periodEnd" IS NULL
      OR intent."scopeType" NOT IN ('user','api_key','workspace')
      OR intent."scopeId" IS NULL
      OR intent.period NOT IN ('daily','weekly','monthly','lifetime')
    THEN RETURN pg_catalog.jsonb_build_object('status','invalid_admission'); END IF;
    seen_assignments:=pg_catalog.array_append(seen_assignments,
      intent."assignmentId");
    IF intent."assignmentId"='gateway-key-limit:'||q.api_key_id THEN
      supplied_key:=supplied_key+1;
      IF intent."scopeType"<>'api_key' OR intent."scopeId"<>q.api_key_id
        OR intent."guardrailId"<>intent."assignmentId"
        OR key_row.limit_micros IS NULL
        OR intent."limitMicros"<>key_row.limit_micros
        OR intent."guardrailVersion"<>key_row.limit_epoch+1
        OR intent.period<>coalesce(key_row.limit_reset,'lifetime')
      THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
      expected_start:=key_row.created_at;
    ELSIF pg_catalog.left(intent."assignmentId",17)='workspace-budget:' THEN
      supplied_workspace:=supplied_workspace+1;
      SELECT * INTO source_row FROM cinatoken_gateway.workspace_budgets b
        WHERE b.id=pg_catalog.substr(intent."assignmentId",18) FOR SHARE;
      IF NOT FOUND OR intent."scopeType"<>'workspace'
        OR intent."scopeId"<>q.workspace_id
        OR intent."guardrailId"<>intent."assignmentId"
        OR source_row.workspace_id<>q.workspace_id
        OR source_row.limit_micros<>intent."limitMicros"
        OR source_row.config_epoch+1<>intent."guardrailVersion"
        OR source_row.reset_interval<>intent.period
      THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
      expected_start:=workspace_row.created_at;
    ELSE
      supplied_configured:=supplied_configured+1;
      IF intent.period='lifetime' OR intent."scopeType"='workspace'
        OR (intent."scopeType"='user' AND intent."scopeId"<>q.user_id)
        OR (intent."scopeType"='api_key' AND intent."scopeId"<>q.api_key_id)
      THEN RETURN pg_catalog.jsonb_build_object('status','invalid_admission'); END IF;
      SELECT g.id,g.designated_version,g.is_workspace_default,
        g.is_account_default,v.config_json::jsonb AS config
        INTO source_row FROM cinatoken_gateway.guardrails g
        JOIN cinatoken_gateway.guardrail_versions v
          ON v.guardrail_id=g.id AND v.version=g.designated_version
        WHERE g.id=intent."guardrailId" AND g.workspace_id=q.workspace_id
          AND g.status='active' FOR SHARE OF g,v;
      IF NOT FOUND OR source_row.is_account_default
        OR source_row.designated_version<>intent."guardrailVersion"
        OR source_row.config->'budget' IS NULL
        OR source_row.config->'budget'='null'::jsonb
        OR source_row.config->'budget'->>'period'<>intent.period
        OR pg_catalog.round((source_row.config->'budget'->>'limit')::numeric
          *1000000)::bigint<>intent."limitMicros"
      THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
      IF source_row.is_workspace_default THEN
        IF (intent."scopeType"='user' AND intent."assignmentId"
              IS DISTINCT FROM 'workspace-default:'||source_row.id||':user')
          OR (intent."scopeType"='api_key' AND intent."assignmentId"
              IS DISTINCT FROM 'workspace-default:'||source_row.id||':api-key')
        THEN RETURN pg_catalog.jsonb_build_object('status','invalid_admission'); END IF;
      ELSIF NOT EXISTS (SELECT 1 FROM cinatoken_gateway.guardrail_assignments ga
          WHERE ga.id=intent."assignmentId" AND ga.guardrail_id=source_row.id
            AND ga.workspace_id=q.workspace_id
            AND ga.scope_type=intent."scopeType"
            AND ga.scope_id=intent."scopeId")
      THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
      expected_start:=NULL;
    END IF;
    IF intent.period='lifetime' THEN
      expected_end:='9999-12-31T23:59:59.999Z'::timestamptz;
    ELSE
      expected_start:=CASE intent.period
        WHEN 'daily' THEN pg_catalog.date_trunc('day',server_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
        WHEN 'weekly' THEN pg_catalog.date_trunc('week',server_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
        ELSE pg_catalog.date_trunc('month',server_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' END;
      expected_end:=CASE intent.period
        WHEN 'daily' THEN expected_start+INTERVAL '1 day'
        WHEN 'weekly' THEN expected_start+INTERVAL '7 days'
        ELSE expected_start+INTERVAL '1 month' END;
    END IF;
    IF intent."periodStart" IS DISTINCT FROM expected_start
      OR intent."periodEnd" IS DISTINCT FROM expected_end
      OR NOT (server_now>=intent."periodStart"
        AND server_now<intent."periodEnd")
    THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
    SELECT * INTO held FROM cinatoken_gateway.guardrail_budget_reservations
      WHERE request_id=v_request_id AND assignment_id=intent."assignmentId"
      FOR UPDATE;
    IF NOT FOUND OR held.workspace_id IS DISTINCT FROM q.workspace_id
      OR held.guardrail_id IS DISTINCT FROM intent."guardrailId"
      OR held.guardrail_version IS DISTINCT FROM intent."guardrailVersion"
      OR held.scope_type IS DISTINCT FROM intent."scopeType"
      OR held.scope_id IS DISTINCT FROM intent."scopeId"
      OR held.period IS DISTINCT FROM intent.period
      OR held.period_start IS DISTINCT FROM intent."periodStart"
      OR held.period_end IS DISTINCT FROM intent."periodEnd"
      OR held.limit_micros IS DISTINCT FROM intent."limitMicros"
      OR held.reserved_micros IS DISTINCT FROM admission.reserved_micros
      OR held.settlement_basis IS DISTINCT FROM 'charged'
      OR held.state IS DISTINCT FROM 'reserved'
      OR held.dispatched_at IS NOT NULL OR held.expires_at<=server_now
    THEN RETURN pg_catalog.jsonb_build_object('status','missing_hold'); END IF;
    SELECT * INTO window_row FROM cinatoken_gateway.guardrail_budget_windows
      WHERE workspace_id=held.workspace_id AND scope_type=held.scope_type
        AND scope_id=held.scope_id AND period=held.period
        AND period_start=held.period_start FOR UPDATE;
    SELECT coalesce(pg_catalog.sum(reserved_micros),0)::bigint INTO active_micros
      FROM cinatoken_gateway.guardrail_budget_reservations
      WHERE workspace_id=held.workspace_id AND scope_type=held.scope_type
        AND scope_id=held.scope_id AND period=held.period
        AND period_start=held.period_start
        AND state IN ('reserved','dispatched');
    IF window_row.workspace_id IS NULL
      OR window_row.reserved_micros<>active_micros
      OR window_row.period_end IS DISTINCT FROM held.period_end
    THEN RETURN pg_catalog.jsonb_build_object('status','hold_counter_differs'); END IF;
  END LOOP;
  IF guardrail_count<>admission.guardrail_count
    OR (SELECT pg_catalog.count(*) FROM
      cinatoken_gateway.guardrail_budget_reservations
      WHERE request_id=v_request_id)<>guardrail_count
  THEN RETURN pg_catalog.jsonb_build_object('status','missing_hold'); END IF;
  SELECT pg_catalog.count(*) INTO expected_count
    FROM cinatoken_gateway.workspace_budgets
    WHERE workspace_id=q.workspace_id;
  IF supplied_workspace<>expected_count
    OR (key_row.limit_micros IS NULL AND supplied_key<>0)
    OR (key_row.limit_micros IS NOT NULL AND supplied_key<>1)
  THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;
  SELECT coalesce(pg_catalog.sum(CASE WHEN g.is_workspace_default
      THEN 2 ELSE 1 END),0)::integer INTO expected_count
    FROM cinatoken_gateway.guardrails g
    JOIN cinatoken_gateway.guardrail_versions v
      ON v.guardrail_id=g.id AND v.version=g.designated_version
    LEFT JOIN cinatoken_gateway.guardrail_assignments ga
      ON NOT g.is_workspace_default AND ga.guardrail_id=g.id
      AND ga.workspace_id=q.workspace_id
      AND ((ga.scope_type='user' AND ga.scope_id=q.user_id)
        OR (ga.scope_type='api_key' AND ga.scope_id=q.api_key_id))
    WHERE g.workspace_id=q.workspace_id AND g.status='active'
      AND NOT g.is_account_default
      AND (g.is_workspace_default OR ga.id IS NOT NULL)
      AND v.config_json::jsonb->'budget' IS NOT NULL
      AND v.config_json::jsonb->'budget'<>'null'::jsonb;
  IF supplied_configured<>expected_count
  THEN RETURN pg_catalog.jsonb_build_object('status','stale_guardrail_source'); END IF;

  IF admission.ordinary_status='reserved' THEN
    SELECT * INTO ordinary FROM cinatoken_gateway.user_budget_reservations
      WHERE request_id=v_request_id FOR UPDATE;
    IF NOT FOUND OR ordinary.user_id IS DISTINCT FROM q.user_id
      OR ordinary.api_key_id IS DISTINCT FROM q.api_key_id
      OR ordinary.budget_epoch IS DISTINCT FROM q.budget_epoch
      OR ordinary.reserved_micros IS DISTINCT FROM admission.reserved_micros
      OR ordinary.state IS DISTINCT FROM 'reserved'
      OR ordinary.dispatched_at IS NOT NULL OR ordinary.expires_at<=server_now
      OR user_row.budget_max IS NULL
      OR user_row.budget_reserved_micros<ordinary.reserved_micros
      OR (user_row.budget_period<>'none'
        AND user_row.budget_reset_at IS NOT NULL
        AND user_row.budget_reset_at<=server_now)
    THEN RETURN pg_catalog.jsonb_build_object('status','missing_hold'); END IF;
    SELECT coalesce(pg_catalog.sum(reserved_micros),0)::bigint
      INTO active_micros FROM cinatoken_gateway.user_budget_reservations
      WHERE user_id=q.user_id AND budget_epoch=q.budget_epoch
        AND state IN ('reserved','dispatched');
    IF active_micros<>user_row.budget_reserved_micros
      OR ordinary.limit_micros<>LEAST(pg_catalog.round(
        GREATEST(user_row.budget_max,0::numeric)*1000000::numeric),
        9007199254740991::numeric)::bigint
    THEN RETURN pg_catalog.jsonb_build_object('status','hold_counter_differs'); END IF;
  ELSE
    IF user_row.budget_max IS NOT NULL OR EXISTS (
      SELECT 1 FROM cinatoken_gateway.user_budget_reservations
        WHERE request_id=v_request_id)
    THEN RETURN pg_catalog.jsonb_build_object('status','missing_hold'); END IF;
  END IF;

  -- Every lock wait above can cross a deadline. No caller clock is trusted.
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR admission.expires_at<=server_now
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
    OR (admission.ordinary_status='reserved'
      AND ordinary.expires_at<=server_now)
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.guardrail_budget_reservations
      WHERE request_id=v_request_id AND expires_at<=server_now)
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;
  send_expires:=LEAST(q.expires_at,admission.expires_at,
    server_now+INTERVAL '30 seconds');
  recovery_expires:=server_now+INTERVAL '15 minutes';
  IF send_expires<=server_now OR recovery_expires<send_expires
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;
  SELECT coalesce(pg_catalog.max(attempt_number),0)+1 INTO v_attempt_number
    FROM cinatoken_gateway.complete_text_attempt_grants_v362
    WHERE request_id=v_request_id;
  IF v_attempt_number NOT BETWEEN 1 AND 3
  THEN RETURN pg_catalog.jsonb_build_object('status','attempt_exhausted'); END IF;

  -- Exact hold state/lease transition and unknown obligation are one COMMIT.
  -- Existing v350/v351 mark functions require the admission SESSION_USER;
  -- the granter therefore performs their counter/limit/window checks above.
  IF admission.ordinary_status='reserved' THEN
    UPDATE cinatoken_gateway.user_budget_reservations SET
      state='dispatched',dispatched_at=server_now,
      expires_at=recovery_expires,updated_at=server_now
      WHERE request_id=v_request_id AND state='reserved';
    IF NOT FOUND THEN RAISE EXCEPTION 'ordinary hold changed before grant'
      USING ERRCODE='P0001'; END IF;
  END IF;
  IF guardrail_count>0 THEN
    UPDATE cinatoken_gateway.guardrail_budget_reservations SET
      state='dispatched',dispatched_at=server_now,
      expires_at=recovery_expires,updated_at=server_now
      WHERE request_id=v_request_id AND state='reserved';
    GET DIAGNOSTICS expected_count=ROW_COUNT;
    IF expected_count<>guardrail_count THEN
      RAISE EXCEPTION 'Guardrail hold changed before grant'
        USING ERRCODE='P0001'; END IF;
  END IF;
  IF (admission.ordinary_status='reserved' AND NOT EXISTS (
      SELECT 1 FROM cinatoken_gateway.user_budget_reservations
      WHERE request_id=v_request_id AND state='dispatched'
        AND expires_at>=recovery_expires))
    OR (SELECT pg_catalog.count(*) FROM
      cinatoken_gateway.guardrail_budget_reservations
      WHERE request_id=v_request_id AND state='dispatched'
        AND expires_at>=recovery_expires)<>guardrail_count
  THEN RAISE EXCEPTION 'complete text grant hold coverage differs'
    USING ERRCODE='P0001'; END IF;
  grant_uuid:=pg_catalog.gen_random_uuid();
  INSERT INTO cinatoken_gateway.complete_text_attempt_grants_v362
    (grant_id,request_id,quote_id,attempt_nonce,attempt_number,
      final_body_sha256,candidate_index,model_id,route_target_id,
      provider_id,endpoint_id,credential_class,credential_id,
      provider_ciphertext_sha256,manifest_source_generation,
      manifest_attested_source_sha256,manifest_source_sha256,
      prepared_route_source_sha256,method,upstream_url_sha256,
      outbound_body_sha256,outbound_body_canonical_sha256,
      outbound_body_bytes,credential_fingerprint_sha256,claim_sha256,
      obligation_state,granted_at,send_expires_at,hold_recovery_expires_at)
    VALUES(grant_uuid,v_request_id,v_quote_id,p_attempt_nonce,v_attempt_number,
      q.final_body_sha256,chosen.candidate_index,chosen.model_id,
      chosen.route_target_id,chosen.provider_id,chosen.endpoint_id,
      chosen.credential_class,chosen.credential_id,
      chosen.provider_ciphertext_sha256,chosen.source_generation,
      chosen.attested_source_sha256,chosen.source_sha256,
      p_claim->>'preparedRouteSourceSha256','POST',
      p_claim->>'upstreamUrlSha256',p_claim->>'outboundBodySha256',
      p_claim->>'outboundBodyCanonicalSha256',
      (p_claim->>'outboundBodyBytes')::integer,
      p_claim->>'credentialFingerprintSha256',claim_sha,
      'unknown',server_now,send_expires,recovery_expires);
  -- The DB cannot know its own COMMIT/connection-close acknowledgement.
  RETURN p_claim || pg_catalog.jsonb_build_object(
    'status','grant_recorded','grantId',grant_uuid,
    'attemptNumber',v_attempt_number,
    'manifestSourceGeneration',chosen.source_generation,
    'currentSourceGeneration',chosen.source_generation,
    'manifestAttestedSourceSha256',chosen.attested_source_sha256,
    'currentAttestedSourceSha256',chosen.attested_source_sha256,
    'manifestSourceSha256',chosen.source_sha256,
    'expiresAt',send_expires,
    'holdRecoveryExpiresAt',recovery_expires);
END;
$grant$;
-- END narrow v362 inherited grant typed-row declaration repair
-- BEGIN unchanged frozen v396 action DDL
CREATE TABLE cinatoken_gateway.routing_policy_epoch_v396(singleton boolean PRIMARY KEY CHECK(singleton),epoch bigint NOT NULL CHECK(epoch BETWEEN 1 AND 9223372036854775806));
INSERT INTO cinatoken_gateway.routing_policy_epoch_v396 VALUES(true,1);
CREATE TABLE cinatoken_gateway.complete_text_routing_facts_v396(model_id text PRIMARY KEY,routing_epoch bigint NOT NULL,expires_at timestamptz NOT NULL,facts jsonb NOT NULL);
CREATE TABLE cinatoken_gateway.complete_text_routing_projections_v396(
 quote_id uuid PRIMARY KEY REFERENCES cinatoken_gateway.complete_text_quotes_v360(quote_id),request_id text NOT NULL UNIQUE,
 routing_epoch bigint NOT NULL,final_body_sha256 text NOT NULL CHECK(final_body_sha256~'^[0-9a-f]{64}$'),expires_at timestamptz NOT NULL,projection jsonb NOT NULL);
CREATE TABLE cinatoken_gateway.complete_text_routing_members_v396(
 quote_id uuid NOT NULL REFERENCES cinatoken_gateway.complete_text_routing_projections_v396(quote_id),candidate_index integer NOT NULL CHECK(candidate_index BETWEEN 0 AND 7),
 model_id text NOT NULL,route_target_id text NOT NULL,provider_id text NOT NULL,endpoint_id text NOT NULL,route_pool_id text,
 source_generation bigint NOT NULL,attested_source_sha256 text NOT NULL CHECK(attested_source_sha256~'^[0-9a-f]{64}$'),beneficial_cache_read_pricing boolean NOT NULL,default_endpoint_eligible boolean NOT NULL,
 PRIMARY KEY(quote_id,route_target_id));
-- SHARE table locks need stronger authority than SELECT. The trusted reader
-- calls this narrow definer instead of receiving source UPDATE privileges.
CREATE FUNCTION cinatoken_gateway.lock_complete_text_routing_sources_v396() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp SET lock_timeout TO '2s' SET statement_timeout TO '15s' AS $lock$
BEGIN
 IF SESSION_USER<>'cinatoken_gateway_route_source_verifier' OR current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'invalid routing source reader'; END IF;
 LOCK TABLE cinatoken_gateway.models,cinatoken_gateway.model_surfaces,cinatoken_gateway.system_config,cinatoken_gateway.model_routes,
  cinatoken_gateway.providers,cinatoken_gateway.route_pools,cinatoken_gateway.model_endpoints,cinatoken_gateway.model_endpoint_routes,
  cinatoken_gateway.route_source_generations_v359 IN SHARE MODE NOWAIT;
 IF NOT pg_catalog.pg_try_advisory_xact_lock_shared(746923596) THEN
  RAISE EXCEPTION 'routing policy writer busy' USING ERRCODE='55P03',CONSTRAINT='complete_text_routing_writer_busy_v396';
 END IF;
END;
$lock$;
CREATE FUNCTION cinatoken_gateway.invalidate_routing_policy_v396() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $invalidate$
BEGIN
 IF TG_TABLE_SCHEMA<>'cinatoken_gateway' OR TG_TABLE_NAME NOT IN('models','model_surfaces','system_config','model_routes','providers','route_pools','model_endpoints','model_endpoint_routes') THEN RAISE EXCEPTION 'invalid routing trigger'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(746923596);
 UPDATE cinatoken_gateway.routing_policy_epoch_v396 SET epoch=epoch+1 WHERE singleton;
 RETURN NULL;
END;
$invalidate$;
DO $triggers$
DECLARE tab text;
BEGIN
 FOREACH tab IN ARRAY ARRAY['models','model_surfaces','system_config','model_routes','providers','route_pools','model_endpoints','model_endpoint_routes'] LOOP
  EXECUTE pg_catalog.format('CREATE TRIGGER routing_policy_v396_%I BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON cinatoken_gateway.%I FOR EACH STATEMENT EXECUTE FUNCTION cinatoken_gateway.invalidate_routing_policy_v396()',tab,tab);
 END LOOP;
END;
$triggers$;
CREATE FUNCTION cinatoken_gateway.attest_complete_text_routing_v396(p_epoch bigint,p_facts jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $attest$
DECLARE item jsonb; route jsonb; current_epoch bigint; expiry timestamptz; selected_surface record;
BEGIN
 IF SESSION_USER<>'cinatoken_gateway_route_source_verifier' OR pg_catalog.current_setting('transaction_isolation')<>'read committed'
  OR p_epoch IS NULL OR p_epoch<1 OR jsonb_typeof(p_facts)<>'array' OR jsonb_array_length(p_facts) NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'invalid routing attestation'; END IF;
 LOCK TABLE cinatoken_gateway.models,cinatoken_gateway.model_surfaces,cinatoken_gateway.system_config,cinatoken_gateway.model_routes,
  cinatoken_gateway.providers,cinatoken_gateway.route_pools,cinatoken_gateway.model_endpoints,cinatoken_gateway.model_endpoint_routes,
  cinatoken_gateway.route_source_generations_v359 IN SHARE MODE NOWAIT;
 IF NOT pg_catalog.pg_try_advisory_xact_lock_shared(746923596) THEN
  RAISE EXCEPTION 'routing policy writer busy' USING ERRCODE='55P03',CONSTRAINT='complete_text_routing_writer_busy_v396';
 END IF;
 SELECT epoch INTO current_epoch FROM cinatoken_gateway.routing_policy_epoch_v396 WHERE singleton;
 IF current_epoch<>p_epoch THEN RETURN jsonb_build_object('status','stale'); END IF;
 IF (SELECT count(DISTINCT f->>'modelId') FROM jsonb_array_elements(p_facts) f)<>jsonb_array_length(p_facts) THEN RAISE EXCEPTION 'duplicate model facts'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
  IF jsonb_typeof(item)<>'object' OR (SELECT string_agg(key,',' ORDER BY key) FROM jsonb_object_keys(item) key)<>'expiresAt,modelId,routes,routingEpoch,strategy,surface'
   OR item->>'routingEpoch'<>p_epoch::text OR octet_length(item->>'modelId') NOT BETWEEN 1 AND 240
   OR jsonb_typeof(item->'routes')<>'array' OR jsonb_array_length(item->'routes')>100
   OR jsonb_typeof(item->'strategy')<>'object' OR (SELECT string_agg(key,',' ORDER BY key) FROM jsonb_object_keys(item->'strategy') key)<>'base,tierOverrides'
   OR item->'strategy'->>'base' NOT IN('hash_affinity','weighted_random','weight_priority','weighted_round_robin')
   OR jsonb_typeof(item->'strategy'->'tierOverrides')<>'array' OR jsonb_array_length(item->'strategy'->'tierOverrides')>100
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(item->'strategy'->'tierOverrides') t
    WHERE jsonb_typeof(t)<>'object' OR (SELECT string_agg(key,',' ORDER BY key) FROM jsonb_object_keys(t) key)<>'priority,strategy'
     OR t->>'priority'!~'^-?[0-9]+$' OR abs((t->>'priority')::numeric)>9007199254740991
     OR t->>'strategy' NOT IN('hash_affinity','weighted_random','weight_priority','weighted_round_robin'))
  THEN RAISE EXCEPTION 'invalid safe routing facts'; END IF;
  expiry:=(item->>'expiresAt')::timestamptz;
  IF expiry<=clock_timestamp() OR expiry>clock_timestamp()+interval '61 seconds' THEN RAISE EXCEPTION 'invalid routing facts expiry'; END IF;
  SELECT ms.id,ms.route_pool_id,ms.request_operation,rp.sticky_enabled,rp.sticky_idle_ttl_seconds,rp.sticky_epoch INTO selected_surface
   FROM cinatoken_gateway.model_surfaces ms JOIN cinatoken_gateway.route_pools rp ON rp.id=ms.route_pool_id
   WHERE ms.model_id=item->>'modelId' AND lower(ms.route_group)='default' AND lower(ms.request_protocol)='openai'
    AND ms.request_operation IN('chat','*') AND ms.status='active' AND rp.status='active'
   ORDER BY CASE WHEN ms.request_operation='chat' THEN 0 ELSE 1 END LIMIT 1;
  IF (selected_surface.id IS NULL AND item->'surface'<>'null'::jsonb) OR (selected_surface.id IS NOT NULL AND item->'surface' IS DISTINCT FROM jsonb_build_object(
   'id',selected_surface.id,'poolId',selected_surface.route_pool_id,'match',CASE WHEN selected_surface.request_operation='chat' THEN 'exact' ELSE 'wildcard' END,
   'sticky',jsonb_build_object('enabled',selected_surface.sticky_enabled,'idleTtlSeconds',greatest(60,least(86400,selected_surface.sticky_idle_ttl_seconds)),'epoch',selected_surface.sticky_epoch))) THEN RAISE EXCEPTION 'routing surface differs'; END IF;
  FOR route IN SELECT value FROM jsonb_array_elements(item->'routes') LOOP
   IF jsonb_typeof(route)<>'object' OR (SELECT string_agg(key,',' ORDER BY key) FROM jsonb_object_keys(route) key)<>'attestedSourceSha256,beneficialCacheReadPricing,defaultEndpointEligible,endpointClass,endpointId,maxCompletionTokens,priceScore,providerId,routePoolId,routePriority,routeWeight,sourceGeneration,targetId'
    OR jsonb_typeof(route->'beneficialCacheReadPricing')<>'boolean' OR jsonb_typeof(route->'defaultEndpointEligible')<>'boolean'
    OR jsonb_typeof(route->'routePriority')<>'number' OR (route->>'routePriority')::numeric<>trunc((route->>'routePriority')::numeric)
    OR abs((route->>'routePriority')::numeric)>9007199254740991 OR jsonb_typeof(route->'routeWeight')<>'number' OR (route->>'routeWeight')::numeric<=0
    OR (route->'priceScore'<>'null'::jsonb AND (jsonb_typeof(route->'priceScore')<>'number' OR (route->>'priceScore')::numeric<0))
    OR NOT EXISTS(SELECT 1 FROM cinatoken_gateway.model_routes r JOIN cinatoken_gateway.providers p ON p.id=r.provider_id
     JOIN cinatoken_gateway.model_endpoint_routes er ON er.route_target_id=r.id JOIN cinatoken_gateway.model_endpoints e ON e.id=er.endpoint_id
     JOIN cinatoken_gateway.route_source_generations_v359 f ON f.route_target_id=r.id
     WHERE r.id=route->>'targetId' AND r.model_id=item->>'modelId' AND r.status='active' AND p.status='active'
      AND r.provider_id=route->>'providerId' AND r.route_pool_id IS NOT DISTINCT FROM route->>'routePoolId'
      AND r.priority::numeric=(route->>'routePriority')::numeric AND CASE WHEN r.weight>0 THEN r.weight ELSE 1 END=(route->>'routeWeight')::numeric
      AND e.id=route->>'endpointId' AND e.model_id=r.model_id AND e.provider_id=r.provider_id AND e.status='verified'
      AND e.verified_at<=clock_timestamp() AND e.expires_at>=expiry AND e.endpoint_class IS NOT DISTINCT FROM route->>'endpointClass'
      AND e.max_completion_tokens IS NOT DISTINCT FROM (route->>'maxCompletionTokens')::bigint
      AND f.generation::text=route->>'sourceGeneration' AND f.verified_generation=f.generation AND f.attested_source_sha256=route->>'attestedSourceSha256'
      AND f.verified_subject_fingerprint=er.subject_fingerprint
      AND (CASE WHEN selected_surface.id IS NOT NULL THEN r.route_pool_id=selected_surface.route_pool_id ELSE lower(coalesce(nullif(btrim(r.route_group),''),'default'))='default' END))
   THEN RAISE EXCEPTION 'routing source differs'; END IF;
  END LOOP;
  INSERT INTO cinatoken_gateway.complete_text_routing_facts_v396 VALUES(item->>'modelId',p_epoch,expiry,item)
   ON CONFLICT(model_id) DO UPDATE SET routing_epoch=excluded.routing_epoch,expires_at=excluded.expires_at,facts=excluded.facts;
 END LOOP;
 RETURN jsonb_build_object('status','routing_attested','routingEpoch',p_epoch::text,'modelCount',jsonb_array_length(p_facts));
END;
$attest$;
CREATE FUNCTION cinatoken_gateway.require_current_routing_projection_v396(p_quote uuid,p_epoch bigint,p_candidate integer,p_allow_expired boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $require$
DECLARE projection record; current_epoch bigint;
BEGIN
 -- Existing send wrappers already hold source relation SHARE locks. Never wait
 -- here for a writer that holds the exclusive epoch gate and needs those locks.
 IF NOT pg_catalog.pg_try_advisory_xact_lock_shared(746923596) THEN
  RAISE EXCEPTION 'routing policy writer busy' USING ERRCODE='55P03',CONSTRAINT='complete_text_routing_writer_busy_v396';
 END IF;
 SELECT epoch INTO current_epoch FROM cinatoken_gateway.routing_policy_epoch_v396 WHERE singleton;
 SELECT * INTO projection FROM cinatoken_gateway.complete_text_routing_projections_v396 WHERE quote_id=p_quote FOR SHARE;
 IF NOT FOUND OR p_epoch IS NULL OR p_candidate IS NULL OR p_allow_expired IS NULL OR p_candidate NOT BETWEEN 0 AND 7
  OR projection.routing_epoch<>p_epoch OR current_epoch<>p_epoch OR (NOT p_allow_expired AND projection.expires_at<=clock_timestamp())
  OR jsonb_array_length(projection.projection->'candidates')<=p_candidate
  OR EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_routing_members_v396 m
   LEFT JOIN cinatoken_gateway.route_source_generations_v359 f ON f.route_target_id=m.route_target_id
   WHERE m.quote_id=p_quote AND (f.generation IS DISTINCT FROM m.source_generation OR f.verified_generation IS DISTINCT FROM f.generation
    OR f.attested_source_sha256 IS DISTINCT FROM m.attested_source_sha256))
 THEN RAISE EXCEPTION 'routing projection stale' USING ERRCODE='23514',CONSTRAINT='complete_text_routing_freshness_v396'; END IF;
END;
$require$;
CREATE FUNCTION cinatoken_gateway.require_current_routing_projection_v396(p_quote uuid,p_epoch bigint,p_candidate integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $require$
BEGIN PERFORM cinatoken_gateway.require_current_routing_projection_v396(p_quote,p_epoch,p_candidate,false); END;
$require$;
CREATE FUNCTION cinatoken_gateway.fence_complete_text_routing_v396() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $fence$
DECLARE grant_row record; p record;
BEGIN
 IF TG_TABLE_NAME='complete_text_attempt_grants_v362' THEN grant_row:=NEW;
 ELSE SELECT * INTO grant_row FROM cinatoken_gateway.complete_text_attempt_grants_v362 WHERE grant_id=NEW.grant_id FOR SHARE; END IF;
 SELECT * INTO p FROM cinatoken_gateway.complete_text_routing_projections_v396 WHERE quote_id=grant_row.quote_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'routing projection missing' USING ERRCODE='23514',CONSTRAINT='complete_text_routing_freshness_v396'; END IF;
 PERFORM cinatoken_gateway.require_current_routing_projection_v396(grant_row.quote_id,p.routing_epoch,grant_row.candidate_index);
 IF p.request_id IS DISTINCT FROM grant_row.request_id OR p.final_body_sha256 IS DISTINCT FROM grant_row.final_body_sha256
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p.projection->'candidates') candidate WHERE NOT EXISTS(
   SELECT 1 FROM cinatoken_gateway.complete_text_routing_members_v396 m
   JOIN cinatoken_gateway.complete_text_quote_routes_v360 quoted ON quoted.quote_id=m.quote_id
    AND quoted.candidate_index=m.candidate_index AND quoted.route_target_id=m.route_target_id
   JOIN cinatoken_gateway.model_endpoints endpoint ON endpoint.id=m.endpoint_id
   WHERE m.quote_id=p.quote_id AND m.candidate_index=(candidate->>'candidateIndex')::integer AND m.default_endpoint_eligible
    AND (coalesce((quoted.source_snapshot->>'requestedOutputTokens')::bigint,0)=0
     OR endpoint.max_completion_tokens>=(quoted.source_snapshot->>'requestedOutputTokens')::bigint)))
  OR NOT EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_routing_members_v396 m
   JOIN cinatoken_gateway.complete_text_quote_routes_v360 quoted ON quoted.quote_id=m.quote_id
    AND quoted.candidate_index=m.candidate_index AND quoted.route_target_id=m.route_target_id
   JOIN cinatoken_gateway.model_endpoints endpoint ON endpoint.id=m.endpoint_id
   WHERE m.quote_id=grant_row.quote_id AND m.default_endpoint_eligible
   AND m.candidate_index=grant_row.candidate_index AND m.model_id=grant_row.model_id AND m.route_target_id=grant_row.route_target_id
   AND m.provider_id=grant_row.provider_id AND m.endpoint_id=grant_row.endpoint_id AND m.source_generation=grant_row.manifest_source_generation
   AND m.attested_source_sha256=grant_row.manifest_attested_source_sha256
   AND (coalesce((quoted.source_snapshot->>'requestedOutputTokens')::bigint,0)=0
    OR endpoint.max_completion_tokens>=(quoted.source_snapshot->>'requestedOutputTokens')::bigint))
 THEN RAISE EXCEPTION 'routing selection differs' USING ERRCODE='23514',CONSTRAINT='complete_text_routing_membership_v396'; END IF;
 RETURN NEW;
END;
$fence$;
CREATE TRIGGER complete_text_routing_v396_grant BEFORE INSERT ON cinatoken_gateway.complete_text_attempt_grants_v362 FOR EACH ROW EXECUTE FUNCTION cinatoken_gateway.fence_complete_text_routing_v396();
CREATE TRIGGER complete_text_routing_v396_custody BEFORE INSERT ON cinatoken_gateway.complete_text_send_custody_v365 FOR EACH ROW EXECUTE FUNCTION cinatoken_gateway.fence_complete_text_routing_v396();
CREATE TRIGGER complete_text_routing_v396_start BEFORE INSERT ON cinatoken_gateway.complete_text_send_starts_v365 FOR EACH ROW EXECUTE FUNCTION cinatoken_gateway.fence_complete_text_routing_v396();
CREATE FUNCTION cinatoken_gateway.reject_routing_projection_mutation_v396() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,pg_temp AS $immutable$
BEGIN RAISE EXCEPTION 'routing projection is immutable' USING ERRCODE='23514'; END;
$immutable$;
CREATE TRIGGER complete_text_routing_projection_immutable_v396 BEFORE UPDATE OR DELETE OR TRUNCATE ON cinatoken_gateway.complete_text_routing_projections_v396 FOR EACH STATEMENT EXECUTE FUNCTION cinatoken_gateway.reject_routing_projection_mutation_v396();
CREATE TRIGGER complete_text_routing_members_immutable_v396 BEFORE UPDATE OR DELETE OR TRUNCATE ON cinatoken_gateway.complete_text_routing_members_v396 FOR EACH STATEMENT EXECUTE FUNCTION cinatoken_gateway.reject_routing_projection_mutation_v396();
CREATE FUNCTION cinatoken_gateway.project_complete_text_routing_v396(
  p_request_id text,p_quote_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path TO pg_catalog, pg_temp
SET lock_timeout TO '2s'
SET statement_timeout TO '15s' AS $plan$
DECLARE q record; cap record; key_row record; user_row record;
DECLARE workspace_row record; manifest record; server_now timestamptz;
DECLARE candidate_count integer; manifest_count integer; active_count integer;
DECLARE max_ceiling bigint; routes jsonb:='[]'::jsonb;
DECLARE policy record; prior record; item record; members jsonb; candidates jsonb:='[]'::jsonb;
DECLARE current_epoch bigint; valid_until timestamptz; safe_projection jsonb;
BEGIN
  IF SESSION_USER<>'cinatoken_gateway_complete_text_routing_projector'
    OR pg_catalog.current_setting('transaction_isolation')<>'read committed'
    OR p_request_id IS NULL OR pg_catalog.length(p_request_id) NOT BETWEEN 1 AND 128
    OR p_quote_id IS NULL
  THEN RAISE EXCEPTION 'invalid complete text plan call'
    USING ERRCODE='23514',CONSTRAINT='complete_text_plan_call_v365'; END IF;
  SELECT * INTO q FROM cinatoken_gateway.complete_text_quotes_v360
    WHERE request_id=p_request_id AND quote_id=p_quote_id FOR SHARE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','not_found'); END IF;

  SELECT * INTO cap FROM cinatoken_gateway.authenticated_request_capabilities_v356
    WHERE request_id=q.request_id FOR SHARE;
  SELECT * INTO key_row FROM cinatoken_gateway.api_keys
    WHERE id=q.api_key_id FOR SHARE;
  SELECT * INTO user_row FROM cinatoken_gateway.users
    WHERE id=q.user_id FOR SHARE;
  SELECT * INTO workspace_row FROM cinatoken_gateway.workspaces
    WHERE id=q.workspace_id FOR SHARE;
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR q.credential_class IS DISTINCT FROM 'platform'
    OR cap.request_id IS NULL OR cap.state<>'claimed'
    OR cap.invalidated_at IS NOT NULL OR cap.expires_at<=server_now
    OR cap.body_sha256 IS DISTINCT FROM q.original_body_sha256
    OR cap.api_key_id IS DISTINCT FROM q.api_key_id
    OR cap.user_id IS DISTINCT FROM q.user_id
    OR cap.workspace_id IS DISTINCT FROM q.workspace_id
    OR cap.budget_epoch IS DISTINCT FROM q.budget_epoch
    OR cap.key_limit_epoch IS DISTINCT FROM q.key_limit_epoch
    OR key_row.id IS NULL OR key_row.status IS DISTINCT FROM 'active'
    OR key_row.key_hash IS DISTINCT FROM cap.key_hash
    OR key_row.key IS DISTINCT FROM 'hashref:'||cap.key_hash
    OR key_row.user_id IS DISTINCT FROM q.user_id
    OR key_row.workspace_id IS DISTINCT FROM q.workspace_id
    OR key_row.limit_epoch IS DISTINCT FROM q.key_limit_epoch
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
    OR user_row.id IS NULL OR user_row.status IS DISTINCT FROM 'active'
    OR user_row.budget_epoch IS DISTINCT FROM q.budget_epoch
    OR user_row.charged_cost_factors IS NOT NULL
    OR workspace_row.id IS NULL OR workspace_row.status IS DISTINCT FROM 'active'
    OR workspace_row.scope_type IS DISTINCT FROM 'personal'
    OR workspace_row.personal_owner_user_id IS DISTINCT FROM q.user_id
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;

  -- A complete current route predicate is needed even for a read projection.
  -- v362 repeats all authority checks at grant time; this lock only gives the
  -- planner a coherent snapshot for this transaction, not a send lease.
  LOCK TABLE cinatoken_gateway.system_config,cinatoken_gateway.models,
    cinatoken_gateway.model_surfaces,
    cinatoken_gateway.model_routes,
    cinatoken_gateway.route_pools,
    cinatoken_gateway.providers,
    cinatoken_gateway.model_endpoints,
    cinatoken_gateway.model_endpoint_routes,
    cinatoken_gateway.route_source_generations_v359,
    cinatoken_gateway.byok_keys
    IN SHARE MODE NOWAIT;
  IF NOT pg_catalog.pg_try_advisory_xact_lock_shared(746923596) THEN
  RAISE EXCEPTION 'routing policy writer busy' USING ERRCODE='55P03',CONSTRAINT='complete_text_routing_writer_busy_v396';
 END IF;
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR cap.expires_at<=server_now
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.byok_keys b
      WHERE b.workspace_id=q.workspace_id AND b.deleted_at IS NULL
        AND NOT b.disabled)
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;
  candidate_count:=pg_catalog.jsonb_array_length(q.ordered_model_ids);
  SELECT pg_catalog.count(*)::integer,pg_catalog.max(per_attempt_ceiling_micros)
    INTO manifest_count,max_ceiling
    FROM cinatoken_gateway.complete_text_quote_routes_v360
    WHERE quote_id=q.quote_id;
  IF candidate_count NOT BETWEEN 1 AND 8 OR manifest_count<>q.route_count
    OR manifest_count NOT BETWEEN 1 AND 100 OR max_ceiling IS NULL
    OR max_ceiling<=0 OR max_ceiling<>q.max_per_attempt_ceiling_micros
    OR q.three_attempt_ceiling_micros<>max_ceiling*3
  THEN RETURN pg_catalog.jsonb_build_object('status','invalid_manifest'); END IF;

  FOR manifest IN SELECT * FROM cinatoken_gateway.complete_text_quote_routes_v360
    WHERE quote_id=q.quote_id ORDER BY candidate_index,route_target_id
  LOOP
    IF manifest.candidate_index NOT BETWEEN 0 AND candidate_count-1
      OR manifest.model_id IS DISTINCT FROM
        q.ordered_model_ids->>manifest.candidate_index
      OR pg_catalog.octet_length(manifest.model_id)>240
      OR pg_catalog.octet_length(manifest.route_target_id)>256
      OR manifest.credential_class IS DISTINCT FROM 'platform'
      OR manifest.credential_id IS DISTINCT FROM manifest.provider_id
      OR manifest.source_sha256 IS DISTINCT FROM pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(
          manifest.source_snapshot::text,'UTF8')),'hex')
      OR manifest.source_snapshot->>'modelId' IS DISTINCT FROM manifest.model_id
      OR manifest.source_snapshot->>'routeTargetId' IS DISTINCT FROM
        manifest.route_target_id
      OR manifest.source_snapshot->>'providerId' IS DISTINCT FROM
        manifest.provider_id
      OR manifest.source_snapshot->>'endpointId' IS DISTINCT FROM
        manifest.endpoint_id
      OR manifest.source_snapshot->>'providerCiphertextSha256' IS DISTINCT FROM
        manifest.provider_ciphertext_sha256
      OR manifest.source_snapshot->>'sourceGeneration' IS DISTINCT FROM
        manifest.source_generation::text
      OR manifest.source_snapshot->>'attestedSourceSha256' IS DISTINCT FROM
        manifest.attested_source_sha256
      OR NOT EXISTS (SELECT 1 FROM cinatoken_gateway.model_routes r
        JOIN cinatoken_gateway.route_pools rp
          ON rp.id=r.route_pool_id AND rp.model_id=r.model_id
            AND rp.route_group=r.route_group
        JOIN cinatoken_gateway.providers po ON po.id=r.provider_id
        JOIN cinatoken_gateway.model_endpoint_routes er
          ON er.route_target_id=r.id
        JOIN cinatoken_gateway.model_endpoints e
          ON e.id=er.endpoint_id AND e.model_id=r.model_id
            AND e.provider_id=r.provider_id
        JOIN cinatoken_gateway.route_source_generations_v359 f
          ON f.route_target_id=r.id
        WHERE r.id=manifest.route_target_id AND r.model_id=manifest.model_id
          AND r.provider_id=manifest.provider_id
          AND r.status='active' AND r.route_group='default'
          AND r.upstream_protocol='openai' AND r.upstream_operation='chat'
          AND r.adapter='passthrough' AND r.price_override IS NULL
          AND r.custom_params IS NULL AND r.routing_metadata IS NULL
          AND rp.status='active' AND po.status='active'
          AND po.shared_channel_type IS NULL AND po.api_key LIKE 'enc:v2:%'
          AND pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(po.api_key,'UTF8')),'hex')
              =manifest.provider_ciphertext_sha256
          AND e.id=manifest.endpoint_id AND e.status='verified'
          AND e.expires_at>server_now
          AND f.generation=manifest.source_generation
          AND f.verified_generation=f.generation
          AND f.attested_source_sha256=manifest.attested_source_sha256
          AND f.verified_subject_fingerprint=er.subject_fingerprint)
    THEN RETURN pg_catalog.jsonb_build_object('status','stale_manifest'); END IF;
    routes:=routes || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'candidateIndex',manifest.candidate_index,
      'modelId',manifest.model_id,
      'routeTargetId',manifest.route_target_id,
      'sourceGeneration',manifest.source_generation::text,
      'attestedSourceSha256',manifest.attested_source_sha256));
  END LOOP;
  SELECT pg_catalog.count(*)::integer INTO active_count
    FROM pg_catalog.jsonb_array_elements_text(q.ordered_model_ids)
      WITH ORDINALITY AS candidates(model_id,ordinal)
    JOIN cinatoken_gateway.model_routes r
      ON r.model_id=candidates.model_id AND r.status='active';
  IF active_count<>manifest_count OR EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_array_elements_text(q.ordered_model_ids)
      WITH ORDINALITY AS candidates(model_id,ordinal)
    JOIN cinatoken_gateway.model_routes r
      ON r.model_id=candidates.model_id AND r.status='active'
    WHERE NOT EXISTS (SELECT 1
      FROM cinatoken_gateway.complete_text_quote_routes_v360 m
      WHERE m.quote_id=q.quote_id AND m.candidate_index=candidates.ordinal-1
        AND m.route_target_id=r.id))
    OR EXISTS (SELECT 1 FROM cinatoken_gateway.model_surfaces s
      JOIN cinatoken_gateway.route_pools rp ON rp.id=s.route_pool_id
      WHERE s.model_id IN (SELECT value FROM pg_catalog.jsonb_array_elements_text(
          q.ordered_model_ids)) AND lower(s.route_group)='default'
        AND lower(s.request_protocol)='openai'
        AND s.request_operation IN ('chat','*') AND s.status='active'
        AND rp.status='active' AND (rp.model_id<>s.model_id OR EXISTS (
          SELECT 1 FROM cinatoken_gateway.model_routes sr
          WHERE sr.route_pool_id=s.route_pool_id AND sr.status='active'
            AND sr.model_id<>s.model_id)))
  THEN RETURN pg_catalog.jsonb_build_object('status','stale_manifest'); END IF;
  server_now:=pg_catalog.clock_timestamp();
  IF q.expires_at<=server_now OR cap.expires_at<=server_now
    OR (key_row.expires_at IS NOT NULL AND key_row.expires_at<=server_now)
  THEN RETURN pg_catalog.jsonb_build_object('status','stale'); END IF;
  SELECT epoch INTO current_epoch FROM cinatoken_gateway.routing_policy_epoch_v396 WHERE singleton;
  SELECT * INTO prior FROM cinatoken_gateway.complete_text_routing_projections_v396 WHERE quote_id=q.quote_id FOR SHARE;
  IF FOUND THEN
    IF prior.routing_epoch<>current_epoch OR prior.expires_at<=server_now THEN
      RETURN pg_catalog.jsonb_build_object('status','stale_projection'); END IF;
    PERFORM cinatoken_gateway.require_current_routing_projection_v396(q.quote_id,current_epoch,0);
    RETURN prior.projection;
  END IF;
  valid_until:=q.expires_at;
  FOR item IN SELECT value AS model_id,ordinality::integer-1 AS candidate_index
    FROM pg_catalog.jsonb_array_elements_text(q.ordered_model_ids) WITH ORDINALITY LOOP
    SELECT * INTO policy FROM cinatoken_gateway.complete_text_routing_facts_v396 WHERE model_id=item.model_id FOR SHARE;
    IF NOT FOUND OR policy.routing_epoch<>current_epoch OR policy.expires_at<=server_now THEN
      RETURN pg_catalog.jsonb_build_object('status','unverified_routing'); END IF;
    valid_until:=least(valid_until,policy.expires_at);
    SELECT coalesce(pg_catalog.jsonb_agg(f.value ORDER BY (f.value->>'routePriority')::bigint DESC,f.ordinality),'[]'::jsonb)
      INTO members FROM pg_catalog.jsonb_array_elements(policy.facts->'routes') WITH ORDINALITY f(value,ordinality)
      JOIN cinatoken_gateway.complete_text_quote_routes_v360 m
        ON m.quote_id=q.quote_id AND m.candidate_index=item.candidate_index AND m.route_target_id=f.value->>'targetId'
        AND m.model_id=item.model_id AND m.provider_id=f.value->>'providerId' AND m.endpoint_id=f.value->>'endpointId'
        AND m.source_generation::text=f.value->>'sourceGeneration' AND m.attested_source_sha256=f.value->>'attestedSourceSha256';
    candidates:=candidates||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'candidateIndex',item.candidate_index,'modelId',item.model_id,'routeGroup','default',
      'requestProtocol','openai','requestOperation','chat','surface',policy.facts->'surface',
      'strategy',policy.facts->'strategy','routes',members));
  END LOOP;
  safe_projection:=pg_catalog.jsonb_build_object('status','routing_projected','requestId',q.request_id,
    'quoteId',q.quote_id,'finalBodySha256',q.final_body_sha256,'modelIds',q.ordered_model_ids,
    'expiresAt',valid_until,'routingEpoch',current_epoch::text,'candidates',candidates);
  INSERT INTO cinatoken_gateway.complete_text_routing_projections_v396
    (quote_id,request_id,routing_epoch,final_body_sha256,expires_at,projection)
    VALUES(q.quote_id,q.request_id,current_epoch,q.final_body_sha256,valid_until,safe_projection);
  INSERT INTO cinatoken_gateway.complete_text_routing_members_v396
    (quote_id,candidate_index,model_id,route_target_id,provider_id,endpoint_id,route_pool_id,source_generation,attested_source_sha256,beneficial_cache_read_pricing,default_endpoint_eligible)
    SELECT q.quote_id,(c->>'candidateIndex')::integer,c->>'modelId',r->>'targetId',r->>'providerId',r->>'endpointId',r->>'routePoolId',
      (r->>'sourceGeneration')::bigint,r->>'attestedSourceSha256',(r->>'beneficialCacheReadPricing')::boolean,(r->>'defaultEndpointEligible')::boolean
    FROM pg_catalog.jsonb_array_elements(candidates) c CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(c->'routes') r;
  RETURN safe_projection;
END;
$plan$;

REVOKE ALL ON cinatoken_gateway.routing_policy_epoch_v396,cinatoken_gateway.complete_text_routing_facts_v396,
 cinatoken_gateway.complete_text_routing_projections_v396,cinatoken_gateway.complete_text_routing_members_v396 FROM PUBLIC,cinatoken_gateway_runtime,cinatoken_gateway_route_source_verifier,cinatoken_gateway_complete_text_routing_projector;
